#include <bits/stdc++.h>

using namespace std;

bool good(int i, int d) {
    return i % d == 0 && i % (1ll * d * d) != 0;
}

void solve() {
    int x, d;
    cin >> x >> d;
    map<pair<int, int>, int> dp;
    dp[{x, 1}] = 1;
    int res = 0;
    vector<int> del;
    for (int i = 1; i * i <= x; ++i) {
        if (x % i == 0) {
            if (good(i, d))
                del.push_back(i);
            if (x != i * i && good(x / i, d))
                del.push_back(x / i);
        }
    }
    while (dp.size()) {
        auto z = *dp.rbegin();
        if (z.first.first == 1) {
            res += z.second;
        }
        for (auto i : del) {
            if (z.first.first % i == 0 && i >= z.first.second) {
                dp[{z.first.first / i, i}] = min(dp[{z.first.first / i, i}] + z.second, 2);
            }
        }
        dp.erase(z.first);
    }
    if (res == 1)
        cout << "NO\n";
    else
        cout << "YES\n";
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--)
        solve();
}

#include <bits/stdc++.h>

using namespace std;

int prime(int x) {
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0)
            return i;
    }
    return -1;
}

void solve() {
    int x, d;
    cin >> x >> d;
    int cnt = 0;
    while (x % d == 0) {
        ++cnt;
        x /= d;
    }
    if (cnt == 1) {
        cout << "NO\n";
        return;
    }
    if (prime(x) != -1) {
        cout << "YES\n";
        return;
    }
    if (prime(d) != -1 && d == prime(d) * prime(d)) {
        if (x == prime(d) && cnt == 3) {
            cout << "NO\n";
            return;
        }
    }
    if (cnt > 2 && prime(d) != -1) {
        cout << "YES\n";
        return;
    }
    cout << "NO\n";
}

